        _e("kv_dsa_trie", "Trie (Prefix Tree)", "algorithms", "class TrieNode:\n    def __init__(self):\n        self.children = {}\n        self.is_end = False\n\nclass Trie:\n    def __init__(self):\n        self.root = TrieNode()\n    \n    def insert(self, word):\n        node = self.root\n        for c in word:\n            if c not in node.children:\n                node.children[c] = TrieNode()\n            node = node.children[c]\n        node.is_end = True\n    \n    def search(self, word):\n        node = self._find(word)\n        return node is not None and node.is_end\n    \n    def starts_with(self, prefix):\n        return self._find(prefix) is not None\n    \n    def _find(self, prefix):\n        node = self.root\n        for c in prefix:\n            if c not in node.children: return None\n            node = node.children[c]\n        return node\n    \n    def autocomplete(self, prefix, limit=10):\n        node = self._find(prefix)\n        if not node: return []\n        results = []\n        def dfs(node, path):\n            if len(results) >= limit: return\n            if node.is_end: results.append(prefix + path)\n            for c, child in sorted(node.children.items()):\n                dfs(child, path + c)\n        dfs(node, '')\n        return results\n\n# Applications: autocomplete, spell check, IP routing, word games", ["algorithms","trie","prefix-tree","autocomplete","data-structure"]),
