        _e("kv_dsa_backtracking", "Backtracking", "algorithms", "# Template\ndef backtrack(state, choices):\n    if is_solution(state):\n        results.append(state.copy())\n        return\n    for choice in choices:\n        if is_valid(state, choice):\n            state.append(choice)       # Make choice\n            backtrack(state, choices)   # Recurse\n            state.pop()                # Undo choice\n\n# N-Queens\ndef solve_queens(n):\n    results = []\n    def backtrack(row, cols, diag1, diag2, board):\n        if row == n:\n            results.append([''.join(r) for r in board])\n            return\n        for col in range(n):\n            if col in cols or (row-col) in diag1 or (row+col) in diag2:\n                continue\n            board[row][col] = 'Q'\n            backtrack(row+1, cols|{col}, diag1|{row-col}, diag2|{row+col}, board)\n            board[row][col] = '.'\n    backtrack(0, set(), set(), set(), [['.']*n for _ in range(n)])\n    return results\n\n# Subsets\ndef subsets(nums):\n    result = []\n    def bt(start, path):\n        result.append(path[:])\n        for i in range(start, len(nums)):\n            path.append(nums[i])\n            bt(i+1, path)\n            path.pop()\n    bt(0, [])\n    return result\n\n# Also: permutations, combination sum, Sudoku solver, word search", ["algorithms","backtracking","recursion","n-queens","subsets","permutations"]),
        _e("kv_dsa_sliding_window", "Sliding Window", "algorithms", "# Fixed window size\ndef max_sum_subarray(arr, k):\n    window_sum = sum(arr[:k])\n    max_sum = window_sum\n    for i in range(k, len(arr)):\n        window_sum += arr[i] - arr[i-k]\n        max_sum = max(max_sum, window_sum)\n    return max_sum\n\n# Variable window (shrinking)\ndef min_window_substring(s, t):\n    from collections import Counter\n    need = Counter(t)\n    missing = len(t)\n    left = start = end = 0\n    for right, c in enumerate(s, 1):\n        if need[c] > 0:\n            missing -= 1\n        need[c] -= 1\n        if missing == 0:  # All chars found\n            while need[s[left]] < 0:\n                need[s[left]] += 1\n                left += 1\n            if not end or right - left < end - start:\n                start, end = left, right\n            need[s[left]] += 1\n            missing += 1\n            left += 1\n    return s[start:end]\n\n# Two pointers\ndef two_sum_sorted(arr, target):\n    lo, hi = 0, len(arr) - 1\n    while lo < hi:\n        s = arr[lo] + arr[hi]\n        if s == target: return [lo, hi]\n        elif s < target: lo += 1\n        else: hi -= 1\n\n# Patterns: max/min subarray, substring problems, container with most water", ["algorithms","sliding-window","two-pointers","substring","subarray"]),
